"""Artifact storage: backend-independent interface for generated files.

The interface is intentionally small and backend-agnostic so an S3-compatible
implementation can replace the local one later without touching callers:

- ``save(key, chunks)``  — stream chunks in, returns size + SHA-256
- ``open(key)``          — stream chunks out (never loads files into memory)
- ``stat(key)`` / ``delete(key)`` / ``exists(key)``

Keys are generated by the service layer (never client filenames) and are
validated defensively by every backend.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import AsyncIterator
from dataclasses import dataclass


class ArtifactStorageError(Exception):
    """Base error for storage backends (messages are client-safe)."""


class InvalidStorageKeyError(ArtifactStorageError):
    """The requested key is malformed or escapes the storage root."""


class ArtifactNotFoundError(ArtifactStorageError):
    """The key does not exist in the backend."""


class ArtifactSizeLimitExceededError(ArtifactStorageError):
    """The streamed content exceeded the configured size limit."""


@dataclass(frozen=True)
class StoredArtifact:
    """Result of a successful streaming write."""

    key: str
    size_bytes: int
    sha256: str


@dataclass(frozen=True)
class ArtifactStat:
    key: str
    size_bytes: int


class ArtifactStorage(ABC):
    """Backend-agnostic artifact storage contract (async, streaming)."""

    @abstractmethod
    async def save(self, key: str, chunks: AsyncIterator[bytes]) -> StoredArtifact:
        """Stream *chunks* to *key* atomically; returns size and checksum.

        Implementations must write to a temporary location and move into place
        only on success, cleaning up partial files on any failure.
        """

    @abstractmethod
    def open(self, key: str) -> AsyncIterator[bytes]:
        """Stream the stored object in bounded chunks."""

    @abstractmethod
    async def stat(self, key: str) -> ArtifactStat | None:
        """Return size information for *key*, or None when absent."""

    @abstractmethod
    async def delete(self, key: str) -> None:
        """Delete *key*; deleting a missing key must not raise."""

    @abstractmethod
    async def exists(self, key: str) -> bool:
        """True when *key* is stored."""
